// Quota gateway, per docs/ADR-0014.md ("ADR-0042: Rate-limit header behavior").
//
// Contract:
//   - Every response carries `X-Rate-Limit` (exact casing/hyphenation) with the
//     remaining quota as a decimal string.
//   - When the quota is exhausted the gateway returns HTTP 429 and additionally
//     emits `Retry-After: 30` (this exhaustion behavior comes from ADR-0027,
//     which supersedes ADR-0019).
//   - Malformed variants (`RateLimit`, `rate-limit`, `rate_limit`,
//     `X-Rate-Limit-Remaining`) must never appear.
function respond(status, quotaRemaining) {
    const headers = {
        'X-Rate-Limit': String(quotaRemaining),
    };

    if (quotaRemaining <= 0) {
        headers['Retry-After'] = '30';
    }

    return { status, headers };
}

module.exports = { respond };

